  "capabilities/0000000000manage.pragma.yaml": "apiVersion: pragma/v5\nkind: Capability\nmetadata:\n  id: 0000000000manage\n  name: Pragma management tools\n  description: Host tools for managing Pragma resources, evaluations, Missions, Automations, knowledge revisions, and Skill revisions.\n  tags: [builtin, system, pragma, management]\nspec:\n  adapter: pragma.capability.host@v1\n  binding: binding:pragma.management\n  config:\n    key: pragma.management\n",
